INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 0.0, -363.0, 0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 0, 7001, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 0.0, -363.0, 0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 0, 7002, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (7, 0.0, -363.0, 0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 0, 7003, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, -363.0, 0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 0, 10001, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, -363.0, 0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 0, 10002, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, -363.0, 0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 0, 10003, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (10, 0.0, -363.0, 2104010, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 0, 10004, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (12, 0.0, -416.5, 0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 0, 12001, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 0.0, -363.0, 0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 0, 13001, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 0.0, -363.0, 0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 0, 13002, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 0.0, -363.0, 2104010, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 0, 13003, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (13, 0.0, -363.0, 0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 0, 13004, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 0.0, -363.0, 0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 0, 14001, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 0.0, -363.0, 2104010, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 0, 14002, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 0.0, -363.0, 0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 0, 14003, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (14, 0.0, -363.0, 0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 0, 14004, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (15, 0.0, -470.0, 0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 0, 15001, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 0.0, -363.0, 2104010, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 0, 16001, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 0.0, -363.0, 0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 0, 16002, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 0.0, -363.0, 0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 0, 16003, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (16, 0.0, -363.0, 0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 0, 16004, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (17, 0.0, -363.0, 0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 0, 17002, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 0.0, -363.0, 0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 0, 17004, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 0.0, -363.0, 0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 0, 17005, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 0.0, -363.0, 2104010, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 0, 17006, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (25, 0.0, -363.0, 0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 0, 17007, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18, 0.0, -363.0, 0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 0, 18001, "カリン", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (18, 0.0, -363.0, 0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 0, 18002, "カリン", 2, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19, 0.0, -470.0, 0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 0, 19001, "カリン", 3, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (19, 0.0, -470.0, 0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 0, 19002, "カリン", 4, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20, 0.0, -470.0, 0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 0, 20001, "カリン", 5, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (20, 0.0, -470.0, 0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 0, 20002, "カリン", 6, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 0.0, -363.0, 0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 0, 21001, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 0.0, -363.0, 0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 0, 21002, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 0.0, -363.0, 2104010, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 0, 21003, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (21, 0.0, -363.0, 0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 0, 21004, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22, 0.0, -430.0, 0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 0, 22001, "カリン", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (22, 0.0, -430.0, 0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 0, 22002, "カリン", 2, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23, 0.0, -430.0, 0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 0, 23001, "カリン", 3, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (23, 0.0, -430.0, 0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 0, 23002, "カリン", 4, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 10011, 24001, "エリコ（バレンタイン）", 1, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 4.08, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 10011, 24002, "エリコ（バレンタイン）", 2, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 5.0, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 10011, 24003, "エリコ（バレンタイン）", 3, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 10.11, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 10011, 24004, "エリコ（バレンタイン）", 4, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 4.0, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 10011, 24005, "エリコ（バレンタイン）", 5, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 6.0, 109001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 10011, 24006, "エリコ（バレンタイン）", 6, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 10011, 24007, "エリコ（バレンタイン）", 7, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 10011, 24008, "エリコ（バレンタイン）", 8, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 10011, 24009, "エリコ（バレンタイン）", 9, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 10011, 24010, "エリコ（バレンタイン）", 10, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109002);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 10011, 24011, "シズル（バレンタイン）", 1, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 2.12, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 10011, 24012, "シズル（バレンタイン）", 2, 2, 5, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 4.19, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 10011, 24013, "シズル（バレンタイン）", 3, 4, 2, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 2.3, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 10011, 24014, "シズル（バレンタイン）", 4, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 10011, 24015, "シズル（バレンタイン）", 5, 2, 5, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 5.23, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 10011, 24016, "シズル（バレンタイン）", 6, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 8.0, -385.0, 0, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 10011, 24017, "シズル（バレンタイン）", 7, 2, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 5.01, 109101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 10011, 24018, "シズル（バレンタイン）", 8, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 10011, 24019, "シズル（バレンタイン）", 9, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (24, 0.0, 0.0, 0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 10011, 24020, "シズル（バレンタイン）", 10, 1, 1, "2019/01/31 12:00:00", "2030/12/17 14:59:59", 0.0, 109102);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 0.0, -363.0, 2104010, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 0, 26001, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 0.0, -363.0, 0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 0, 26002, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 0.0, -363.0, 0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 0, 26003, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (26, 0.0, -363.0, 0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 0, 26004, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 0.0, -363.0, 2104010, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 0, 27001, "シェフィ", 1, 1, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 0.0, -363.0, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 0, 27002, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 0.0, -363.0, 0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 0, 27003, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (27, 0.0, -363.0, 0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 0, 27004, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28, 0.0, -363.0, 0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 0, 28001, "カリン", 1, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (28, 0.0, -363.0, 0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 0, 28002, "カリン", 2, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29, 0.0, -409.0, 0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 0, 29001, "カリン", 3, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (29, 0.0, -409.0, 0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 0, 29002, "カリン", 4, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30, 0.0, -409.0, 0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 0, 30001, "カリン", 5, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (30, 0.0, -409.0, 0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 0, 30002, "カリン", 6, 1, 1, "2019/09/24 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31, 0.0, -409.0, 0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 0, 31001, "カリン", 7, 1, 1, "2019/10/31 12:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (31, 0.0, -409.0, 0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 0, 31002, "カリン", 8, 1, 1, "2019/10/31 12:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32, 0.0, -409.0, 0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 0, 32001, "カリン", 1, 1, 1, "2019/12/20 5:00:00", "2020/01/04 4:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (32, 0.0, -409.0, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 0, 32002, "カリン", 2, 1, 1, "2019/12/20 5:00:00", "2020/01/04 4:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33, 0.0, -409.0, 0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 0, 33001, "カリン", 3, 1, 1, "2019/12/20 5:00:00", "2020/01/04 4:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (33, 0.0, -409.0, 0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 0, 33002, "カリン", 4, 1, 1, "2019/12/20 5:00:00", "2020/01/04 4:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34, 0.0, -409.0, 0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 0, 34001, "カリン", 5, 1, 1, "2020/01/04 5:00:00", "2020/01/10 11:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (34, 0.0, -409.0, 0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 0, 34002, "カリン", 6, 1, 1, "2020/01/04 5:00:00", "2020/01/10 11:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38, 0.0, -458.0, 0, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 0, 38001, "ペコリーヌ", 1, 2, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 5.3, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (38, 0.0, -458.0, 0, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 0, 38002, "ペコリーヌ", 2, 2, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 6.5, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (39, 9999.0, 9999.0, 0, "", 0, 39005, "ペコリーヌ", 0, 3, 3, "2020/04/01", "2020/04/08 23:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (40, 0.0, -430.0, 0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 0, 40001, "カリン", 2, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 190801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 0.0, -363.0, 2104010, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 0, 41001, "シェフィ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 0.0, -363.0, 0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 0, 41002, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 0.0, -363.0, 0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 0, 41003, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (41, 0.0, -363.0, 0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 0, 41004, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 0.0, -416.5, 0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 0, 42001, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 0.0, -416.5, 2104010, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 0, 42002, "シェフィ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106401);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 0.0, -416.5, 0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 0, 42003, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (42, 0.0, -416.5, 0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 0, 42004, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 0.0, -363.0, 0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 0, 43001, "ペコリーヌ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105801);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 0.0, -363.0, 0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 0, 43002, "コッコロ", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 105901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (43, 0.0, -363.0, 0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 0, 43003, "キャル", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 106001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (44, 0.0, -416.5, 0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 0, 43004, "アメス", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (44, 0.0, -416.5, 0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 0, 43005, "アメス", 2, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (45, 0.0, -416.5, 0, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 0, 43006, "アメス", 3, 2, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 5.79, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (46, 0.0, -371.5, 0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 0, 46001, "アメス", 1, 1, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 123001);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47, 0.0, -416.5, 0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 0, 47001, "シズル", 1, 2, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 104901);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (47, 0.0, -416.5, 0, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 0, 47002, "リノ", 1, 2, 1, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 9.32, 101101);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (48, 0.0, -470.0, 0, "", 0, 48001, "シズル", 0, 2, 2, "2015/12/17 15:00:00", "2030/12/17 14:59:59", 0.0, 104901);
